package net.sigmabeta.sage.sample.jvm

import java.util.Properties

/**
 * Version metadata generated by the desktop build (`generateBuildInfo` in build.gradle.kts).
 *
 * The resource is regenerated on every build, so the Settings "Build date" row reports when the
 * desktop app was built rather than when it was launched. Falls back to development values if the
 * resource is missing (for example when running a test that does not process resources).
 */
object JvmBuildInfo {
    private val properties: Properties = Properties().apply {
        JvmBuildInfo::class.java
            .getResourceAsStream("/sample-build-info.properties")
            ?.use(::load)
    }

    val versionName: String = properties.getProperty("versionName") ?: "dev"

    val buildTimeMs: Long? = properties.getProperty("buildTimeMs")?.toLongOrNull()

    const val BUILD_BRANCH = "desktop"
}
